public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Iterate over the result map and generate complete bipartite graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        V value = entry.getValue();

        // Add the node to the target graph if it doesnt exist
        if (!target.containsVertex(key)) {
            target.addVertex(key);
        }

        // Add the edge to the target graph
        for (V neighbor : value.getNeighbors()) {
            if (neighbor.getLabel().equals(key) || neighbor.getLabel().equals(value.getLabel())) {
                continue;
            }
            if (!target.containsEdge(key, neighbor.getLabel())) {
                target.addEdge(key, neighbor.getLabel());
            }
        }
    }
}

