public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Create a new bipartite graph with the given target graph
    BipartiteGraph<V, E> bipartiteGraph = new BipartiteGraph<>(target);

    // Get the vertex set of the target graph
    Set<V> vertexSet = target.vertexSet();

    // Initialize the result map with vertices from the vertex set
    for (V vertex : vertexSet) {
        resultMap.put(vertex.toString(), bipartiteGraph.addVertex(vertex));
    }

    // Iterate over the edges of the target graph
    for (V source : vertexSet) {
        for (V target : vertexSet) {
            // If the source and target vertices are not the same
            if (!source.equals(target)) {
                // If the source and target vertices are connected by an edge
                if (target.connects(source)) {
                    // Add a new edge to the bipartite graph
                    bipartiteGraph.addEdge(resultMap.get(source.toString()), resultMap.get(target.toString()));
                }
            }
        }
    }

    // Set the graph of the result map to the constructed bipartite graph
    resultMap.get("graph").set(bipartiteGraph);
}

