    long newTimeBucket = day * dayStep;

    // Return the re-formatted time bucket
    return newTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day bucket
    long dayBucket = timeBucket / (long)Math.pow(10, 8);

    // Calculate the month bucket
    long monthBucket = (timeBucket % (long)Math.pow(10, 8)) / (long)Math.pow(10, 6);

    // Calculate the year bucket
    long yearBucket = timeBucket % (long)Math.pow(10, 6);

    // Calculate the new time bucket
    long newTimeBucket = yearBucket + (monthBucket * dayStep) + dayBucket;

    return newTimeBucket;
}

