public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;

    while (index < len) {
        final char c = str.charAt(index++);

        if (c < 0x80) {
            size++;
        } else if (c < 0x800) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            final char low = str.charAt(index++);
            if (Character.isLowSurrogate(low) && Character.isSupplementaryCodePoint(c * 0x400 + low)) {
                size += 4;
            } else {
                throw new IllegalArgumentException("Illegal surrogate: " + c + low);
            }
        } else {
            size += 3;
        }
    }

    return size;
}

