public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("str cannot be null");
    }

    final ByteBuffer buffer = lb.getBuffer();
    int strLen = str.length();
    int start = 0;
    int i = 0;

    while (i < strLen) {
        int cp = str.charAt(i);

        if (cp < 0x80 && cp != 0) {
            // 1-byte utf8 encoding
            if (buffer.hasFreeBytes()) {
                buffer.put((byte)cp);
            }
            i++;
            continue;
        }

        if (cp == 0) {
            // terminator
            break;
        }

        if (cp < 0x800) {
            // 2-byte utf8 encoding
            if (buffer.hasFreeBytes(2)) {
                buffer.put((byte)(0xc0 | (cp >> 6)));
                buffer.put((byte)(0x80 | (cp & 0x3f)));
            }
            i++;
            continue;
        }

        if (cp < 0xffff) {
            // 3-byte utf8 encoding
            if (buffer.hasFreeBytes(3)) {
                buffer.put((byte)(0xe0 | (cp >> 12)));
                buffer.put((byte)(0x80 | ((cp >> 6) & 0x3f)));
                buffer.put((byte)(0x80 | (cp & 0x3f)));
            }
            i++;
            continue;
        }

        // 4-byte utf8 encoding
        if (buffer.hasFreeBytes(4)) {
            buffer.put((byte)(0xf0 | (cp >> 18)));
            buffer.put((byte)(0x80 | ((cp >> 12) & 0x3f)));
            buffer.put((byte)(0x80 | ((cp >> 6) & 0x3f)));
            buffer.put((byte)(0x80 | (cp & 0x3f)));
        }
        i++;
    }
    return lb;
}

