public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder out = new StringBuilder(str.length());
    boolean hadSlash = false;
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (hadSlash) {
            hadSlash = false;
            switch (ch) {
                case 'b':
                    out.append('\b');
                    break;
                case 't':
                    out.append('\t');
                    break;
                case 'n':
                    out.append('\n');
                    break;
                case 'f':
                    out.append('\f');
                    break;
                case 'r':
                    out.append('\r');
                    break;
                case '"':
                    out.append('"');
                    break;
                case '\'':
                    out.append('\'');
                    break;
                case '\\':
                    out.append('\\');
                    break;
                default:
                    throw new Exception("Invalid escaped character: \\" + ch);
            }
        } else {
            out.append(ch);
            if (ch == '\\') {
                hadSlash = true;
            }
        }
    }
    if (hadSlash) {
        throw new Exception("Invalid trailing \\ in string: " + str);
    }
    return out.toString();
}

static String unescapeJava(String str) throws Exception {
    // Check for null input
    if (str == null) {
        return null;
    }

    // Create a buffer for the unescaped string
    StringBuilder buf = new StringBuilder(str.length());

    // Loop through the characters in the input string
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // Check for a backslash and escape sequence
        if (c == '\\') {
            // Get the next character in the input string
            char next = str.charAt(i + 1);

            // Check for a valid escape sequence
            if (next == '\\' || next == 'b' || next == 'f' || next == 'n' || next == 'r' || next == 't' || next == '\"' || next == '\'') {
                // Add the escape character to the buffer
                buf.append(next);

                // Skip the escape character and the escaped character
                i++;
                continue;
            }
        }

        // Add the character to the buffer
        buf.append(c);
    }

    // Return the unescaped string
    return buf.toString();
}

