    Node current = start;
    boolean found = false;

    while (current != stop) {
        if (predicate.test(current)) {
            found = true;
            break;
        }
        current = current.getNext(dir);
    }

    if (found) {
        return Optional.of(new OuterFaceCirculator(current, dir));
    } else {
        return Optional.empty();
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // find the first node on the outer face that satisfies the predicate
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    circulator.setDirection(dir);
    while (circulator.hasNext()) {
        Node current = circulator.next();
        if (predicate.test(current)) {
            return circulator;
        }
    }

    // if no such node is found, return a circulator to the stop node
    circulator.reset();
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (true) {
        Node current = circ.getCurrent();
        if (current == stop) {
            break;
        }
        if (predicate.test(current)) {
            return circ;
        }
        circ.next();
    }
    return null;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    Node current = circulator.current();
    while (!predicate.test(current) && !circulator.atEnd()) {
        if (!circulator.advance()) {
            return circulator;
        }
        current = circulator.current();
    }
    if (circulator.atEnd()) {
        return circulator;
    } else {
        circulator.advance();
        return circulator;
    }
}

