    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            c = input.charAt(i);
            if (c == 'u') {
                sb.append(String.valueOf(Character.toChars(Integer.parseInt(input.substring(i + 1, i + 5), 16))));
                i += 4;
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
