private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add((int) sum);
    }
    return new Pair<>(suffixSum, sum);
}

public static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the result list and sum
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    // Iterate through the bounds list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Compute the suffix sum for the current element
        int suffixSumForCurrentElement = totalSum + bounds.get(i);

        // Add the suffix sum to the result list
        suffixSum.add(suffixSumForCurrentElement);

        // Update the total sum
        totalSum = suffixSumForCurrentElement;
    }

    // Return the computed suffix sum and total sum
    return new Pair<>(suffixSum, totalSum);
}

public static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize variables
    int n = bounds.size();
    long sum = 0L;
    List<Integer> suffixSum = new ArrayList<>(n);

    // Compute the suffix sum and the sum of all elements
    for (int i = n - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add((int) sum);
    }

    // Return the computed pair of suffix sum list and the sum of all elements
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the suffix sum list to have the same size as the input list
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    suffixSum.addAll(Collections.nCopies(bounds.size(), 0));

    // Compute the suffix sum
    for (int i = 0; i < bounds.size(); i++) {
        int sum = 0;
        for (int j = i; j < bounds.size(); j++) {
            sum += bounds.get(j);
            suffixSum.set(j, sum);
        }
    }

    // Compute the sum of all elements
    long totalSum = 0;
    for (int x : bounds) {
        totalSum += x;
    }

    return new Pair<>(suffixSum, totalSum);
}

