        // Get the current list intersection
        ListNodeImpl<E> intersection = list.getIntersection(currentIndex.get());
        // If the intersection is empty, return immediately
        if(intersection == null){
            return;
        }
        // Remove the intersection from the old list
        list.removeIntersection(intersection);
        // Add the intersection to the new list
        addListNode(intersection);
        // Increment the current index
        currentIndex.incrementAndGet();
    }
