			//      the edge e is not in the edge relation for both source and target
			for (E neighborEdge : graph.outgoingEdgesOf(source)) {
				if (neighborEdge == e || visitedEdges.contains(neighborEdge)) {
					continue;
				}
				V neighbor = graph.getEdgeTarget(neighborEdge);
				if (graph.areAdjacent(neighbor, target)) {
					// compute the minimal separator between source and target
					separator.add(new Pair<>(graph.getVertexName(source), graph.getVertexName(target)));
					break;
				}
			}

			// add the separator to the list of minimal separators
			minimalSeparators.add(separator);

			// enqueue the neighboring edges of the current edge
			for (E neighborEdge : graph.outgoingEdgesOf(source)) {
				if (!visitedEdges.contains(neighborEdge)) {
					bfsQueue.add(neighborEdge);
				}
			}
		}
	}

	globalSeparatorList.add(new Pair<>(minimalSeparators, e));
}

return globalSeparatorList;

