public ByteVector putInt(int intValue) {
    // Write the int value to the byte array
    byte[] intBytes = intValue.getBytes();
    // Ensure that the byte array is large enough to hold the int value
    int requiredLength = intBytes.length + 1;
    if (array.length < requiredLength) {
        byte[] newArray = new byte[requiredLength];
        System.arraycopy(array, 0, newArray, 0, array.length);
        array = newArray;
    }
    // Write the int value to the byte array
    System.arraycopy(intBytes, 0, array, array.length - intBytes.length, intBytes.length);
    // Return the updated byte vector
    return this;
}

public ByteVector putInt(int intValue) {
    if (intValue < 0) {
        throw new IllegalArgumentException("intValue must be positive or zero");
    }
    // Calculate how many bytes are needed to represent the int
    int numBytes = (int) Math.ceil(Math.log(intValue) / Math.log(256));
    // Enlarge the byte array if necessary
    if (this.size + numBytes > this.bytes.length) {
        byte[] newBytes = new byte[this.size + numBytes];
        System.arraycopy(this.bytes, 0, newBytes, 0, this.size);
        this.bytes = newBytes;
    }
    // Write the int to the byte array
    for (int i = 0; i < numBytes; i++) {
        this.bytes[this.size + i] = (byte) (intValue % 256);
        intValue >>= 8;
    }
    this.size += numBytes;
    return this;
}

