    if (intValue < 0 || intValue > 0xFF_FF_FF_FF) {
        throw new IllegalArgumentException("Invalid int value: " + intValue);
    }
    int bytes = 4;
    ensureCapacity(bytes);
    while (bytes-- > 0) {
        this.data[this.size++] = (byte)(intValue >> (bytes << 3));
    }
    return this;
}

