    // Check if the intValue fits in a 4-byte integer
    if (intValue < 0 || intValue > 0xFFFFFFFF) {
        throw new IllegalArgumentException("intValue must be between 0 and 0xFFFFFFFF");
    }

    // Calculate the number of bytes needed to represent the intValue
    int numBytes = 4;

    // Check if there is enough capacity in the ByteVector
    if (this.capacity() - this.position() < numBytes) {
        // Enlarge the ByteVector if necessary
        this.enlarge(numBytes);
    }

    // Optimized implementation of putting an int into a byte array
    int v = intValue;
    int index = 0;
    do {
        this.putByte((byte)(v & 0xFF));
        v = v >> 8;
        index++;
    } while (index < numBytes);

    return this;
}

