private static <E,V> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Initialize a boolean variable to keep track of whether the subgraph is complete
    boolean complete = true;

    // Iterate over all edges in the graph
    for (E edge : graph.edges) {
        // Get the endpoints of the edge
        V source = graph.endpoints[edge];
        V target = graph.endpoints[edge];

        // If either endpoint is not in the given set of vertices, the subgraph is not complete
        if (!vertices.contains(source) || !vertices.contains(target)) {
            complete = false;
            break;
        }
    }

    // Return the boolean value indicating whether the subgraph is complete
    return complete;
}

static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Create a new hash set to store the neighbors of each vertex
    HashSet<V> neighbors = new HashSet<>();

    for (V vertex : vertices) {
        // Get the neighbors of `vertex`
        Set<E> edges = graph.edgesOf(vertex);
        for (E edge : edges) {
            // Add the neighbor to `neighbors`
            V neighbor = graph.getEdgeSource(edge) == vertex ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
            neighbors.add(neighbor);
        }
    }

    // Check if all the neighbors of each vertex are present in `vertices`
    for (V vertex : vertices) {
        for (V neighbor : neighbors) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }

    return true;
}

private static boolean isClique(Graph<V,E> graph, Set<V> vertices) {
	Set<E> edges = new HashSet<>();
	for (V vertex : vertices) {
		Set<E> adjEdges = graph.getIncidentEdges(vertex);
		for (E adjEdge : adjEdges) {
			if (vertices.contains(graph.getOpposite(vertex, adjEdge))) {
				edges.add(adjEdge);
			}
		}
	}
	return edges.size() == vertices.size() * (vertices.size() - 1) / 2;
}

