    // Get the contents of the current frame
    Frame currentFrame = typeReconstruction.getCurrentFrame();
    if (currentFrame == null) {
        throw new IllegalStateException("Attempted to pop from an empty frame stack");
    }

    // Get the type of the descriptor
    Type type = Type.getType(descriptor);
    if (type.getSort() != Type.OBJECT && type.getSort() != Type.ARRAY) {
        throw new IllegalArgumentException("Invalid descriptor for popping: " + descriptor);
    }

    // Pop the appropriate number of abstract types based on the descriptor
    if (type.getSort() == Type.OBJECT) {
        // For object types, pop the appropriate number of abstract classes
        int numClasses = Type.getInternalName(type).length - 1;
        for (int i = 0; i < numClasses; i++) {
            currentFrame.popAbstractType();
        }
    } else {
        // For array types, pop the appropriate number of abstract array classes
        int numArrayClasses = Type.getDescriptor(type).length - 1;
        for (int i = 0; i < numArrayClasses; i++) {
            currentFrame.popAbstractArrayType();
        }
    }
}

