public static String applyRelativePath(String path, String relativePath) {
    String[] tokens = path.split("/");
    String[] relativeTokens = relativePath.split("/");

    // Keep track of the current directory
    String currentDir = "";

    // Iterate through the relative path tokens
    for (String token: relativeTokens) {
        // If the token is "..", move up a directory
        if (token.equals("..")) {
            currentDir = currentDir.substring(0, currentDir.lastIndexOf("/"));
        } else if (token.equals(".")) {
            // If the token is ".", do nothing
        } else {
            // Otherwise, add the token to the current directory
            currentDir += token + "/";
        }
    }

    // Join the current directory with the remaining tokens
    String[] newTokens = Arrays.copyOfRange(tokens, currentDir.length(), tokens.length);
    return currentDir + String.join("/", newTokens);
}

