public static String applyRelativePath(String path, String relativePath) {
    // If the path is null, return null
    if (path == null) {
        return null;
    }

    // If the relative path is null or empty, return the original path
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // If the path ends with a separator, remove it
    if (path.endsWith(File.separator)) {
        path = path.substring(0, path.length() - 1);
    }

    // If the relative path starts with a separator, remove it
    if (relativePath.startsWith(File.separator)) {
        relativePath = relativePath.substring(1);
    }

    // Combine the path and relative path
    return path + File.separator + relativePath;
}

