    // Split the path and relative path into individual components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Create a new list to build the result path
    List<String> resultPathComponents = new ArrayList<>();

    // Use two pointers to iterate through the paths and merge the components
    int pathIndex = 0;
    int relativePathIndex = 0;
    while (pathIndex < pathComponents.length && relativePathIndex < relativePathComponents.length) {
        String pathComponent = pathComponents[pathIndex];
        String relativePathComponent = relativePathComponents[relativePathIndex];

        // If the current relative path component is "..", remove the last path component from the result
        if (relativePathComponent.equals("..")) {
            resultPathComponents.remove(resultPathComponents.size() - 1);
        } else {
            // Otherwise, add the path component to the result
            resultPathComponents.add(pathComponent);
        }

        pathIndex++;
        relativePathIndex++;
    }

    // If there are any remaining components in the relative path, add them to the result
    while (relativePathIndex < relativePathComponents.length) {
        resultPathComponents.add(relativePathComponents[relativePathIndex]);
        relativePathIndex++;
    }

    // Join the result components into a single string and return
    return String.join("/", resultPathComponents);
}

