public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Load the file into a byte array
    ByteBuffer contents = Files.map(file);

    // Create a list to store the thread snapshots
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    // Loop through the time ranges
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        // Calculate the start and end times of the range
        long startTime = range.getStartTime();
        long endTime = range.getEndTime();

        // Find the thread dump in the file that contains the start time
        int startIndex = 0;
        for (; startIndex < contents.capacity(); startIndex++) {
            byte b = contents.get(startIndex);
            if (b == '\n') {
                break;
            }
        }

        // Find the thread dump in the file that contains the end time
        int endIndex = startIndex;
        for (; endIndex < contents.capacity(); endIndex++) {
            byte b = contents.get(endIndex);
            if (b == '\n') {
                break;
            }
        }

        // Create a new thread snapshot from the thread dump
        ThreadSnapshot snapshot = new ThreadSnapshot();
        snapshot.setStartTime(startTime);
        snapshot.setEndTime(endTime);
        snapshot.setThreadDump(contents.getString(startIndex, endIndex - startIndex));

        // Add the snapshot to the list
        snapshots.add(snapshot);
    }

    return snapshots;
}

public static List<ThreadSnapshot> loadThreadSnapshotsWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    var threadSnapshots = new ArrayList<ThreadSnapshot>();
    var timeRangeIndex = 0;
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        br.readLine(); // skip header
        while (true) {
            var line = br.readLine();
            if (line == null) {
                break;
            }
            var columns = line.split(",");
            var timestamp = Long.parseLong(columns[0].trim());
            var threadId = Long.parseLong(columns[1].trim());
            var stackTrace = columns[2].trim();
            var timeDelta = timestamp - timeRanges.get(timeRangeIndex).getStart();
            var threadSnapshot = new ThreadSnapshot(threadId, stackTrace, timeDelta);
            threadSnapshots.add(threadSnapshot);
            if (timeDelta > timeRanges.get(timeRangeIndex).getDuration()) {
                timeRangeIndex++;
            }
        }
    }
    return threadSnapshots;
}
